-- =================================================================================
-- 10. Cash Donations & Vouchers Module Schema, RBAC (SAJJAD, IMRAN) & Clean Type-1 Data
-- =================================================================================
SET client_encoding = 'UTF8';

ON CONFLICT (prefix_cd) DO NOTHING;

ON CONFLICT (bank_cd) DO NOTHING;

ON CONFLICT (band_cd) DO NOTHING;

ON CONFLICT (band_det_cd) DO UPDATE SET
    band_det_desc = EXCLUDED.band_det_desc,
    band_det_edesc = EXCLUDED.band_det_edesc;

CREATE TABLE IF NOT EXISTS lkp_payment_types (
    type_cd SMALLINT PRIMARY KEY,
    type_desc VARCHAR(25) NOT NULL,
    type_edesc VARCHAR(30) NOT NULL
);

ON CONFLICT (type_cd) DO UPDATE SET
    type_desc = EXCLUDED.type_desc,
    type_edesc = EXCLUDED.type_edesc;

CREATE TABLE IF NOT EXISTS cash_donors (
    donor_cd INT PRIMARY KEY,
    donor_name VARCHAR(100),
    donor_ename VARCHAR(100),
    donor_address VARCHAR(150),
    tel_home VARCHAR(25),
    tel_office VARCHAR(25),
    mobile VARCHAR(25),
    donor_status SMALLINT NOT NULL DEFAULT 1,
    profession VARCHAR(120),
    dic_representitive VARCHAR(40),
    don_fax VARCHAR(25),
    prefix SMALLINT REFERENCES lkp_name_prefixes(prefix_cd),
    don_reayet VARCHAR(25),
    user_name VARCHAR(30),
    append_date DATE DEFAULT CURRENT_DATE,
    donor_type SMALLINT NOT NULL DEFAULT 1,
    bahrain_status SMALLINT DEFAULT 1,
    data_status SMALLINT,
    sex_cd SMALLINT DEFAULT 1,
    block_no VARCHAR(10),
    followed_by INT,
    donor_importancy_lvl SMALLINT NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS vouch_mstr (
    vouch_no INT NOT NULL,
    donor_type SMALLINT NOT NULL DEFAULT 1,
    donor_code INT NOT NULL REFERENCES cash_donors(donor_cd),
    band_det_cd INT NOT NULL REFERENCES lkp_band_details(band_det_cd),
    trans_date DATE NOT NULL DEFAULT CURRENT_DATE,
    trans_val NUMERIC(10,3) NOT NULL DEFAULT 0.000,
    don_req_desc VARCHAR(150),
    req_reason VARCHAR(200),
    attachments VARCHAR(200),
    trans_pay_type SMALLINT NOT NULL DEFAULT 1 REFERENCES lkp_payment_types(type_cd),
    cheq_visa_no VARCHAR(35),
    bank_cd SMALLINT REFERENCES lkp_banks(bank_cd),
    visa_ex_date DATE,
    nation_cd SMALLINT,
    trns_year SMALLINT NOT NULL,
    user_name VARCHAR(30) NOT NULL,
    amt_txt VARCHAR(250),
    chk_ser VARCHAR(20),
    addresss_tel VARCHAR(100),
    tel VARCHAR(25),
    print_flag SMALLINT DEFAULT 2,
    print_date DATE,
    print_counter SMALLINT DEFAULT 0,
    vouch_no2 INT,
    auto_num SMALLINT DEFAULT 1,
    cancel_replace_notes VARCHAR(250),
    receipt_status SMALLINT NOT NULL DEFAULT 1,
    cancelled_by VARCHAR(30),
    dic_bank SMALLINT REFERENCES lkp_banks(bank_cd),
    dic_account VARCHAR(100),
    PRIMARY KEY (vouch_no, trns_year, donor_type)
);

CREATE TABLE IF NOT EXISTS vouch_history (
    hist_id SERIAL PRIMARY KEY,
    vouch_no INT NOT NULL,
    donor_type SMALLINT DEFAULT 1,
    donor_code VARCHAR(20),
    band_det_cd INT NOT NULL,
    trans_date DATE NOT NULL,
    trans_val NUMERIC(10,3) NOT NULL,
    don_req_desc VARCHAR(150),
    req_reason VARCHAR(200),
    attachments VARCHAR(200),
    trans_pay_type SMALLINT NOT NULL,
    cheq_visa_no VARCHAR(35),
    bank_cd SMALLINT,
    visa_ex_date DATE,
    nation_cd SMALLINT,
    trns_year SMALLINT NOT NULL,
    user_name VARCHAR(30),
    amt_txt VARCHAR(250),
    chk_ser VARCHAR(20),
    addresss_tel VARCHAR(100),
    tel VARCHAR(25),
    print_flag SMALLINT,
    print_date DATE,
    print_counter SMALLINT,
    delete_date DATE DEFAULT CURRENT_DATE,
    action_type VARCHAR(20) DEFAULT 'CANCEL',
    action_by VARCHAR(30),
    action_reason VARCHAR(250),
    action_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_cash_donors_status ON cash_donors(donor_status, donor_type);
CREATE INDEX IF NOT EXISTS idx_cash_donors_name ON cash_donors(donor_name);
CREATE INDEX IF NOT EXISTS idx_cash_donors_ename ON cash_donors(donor_ename);
CREATE INDEX IF NOT EXISTS idx_cash_donors_mobile ON cash_donors(mobile, tel_home, tel_office);
CREATE INDEX IF NOT EXISTS idx_vouch_mstr_year_no ON vouch_mstr(trns_year DESC, vouch_no DESC);
CREATE INDEX IF NOT EXISTS idx_vouch_mstr_donor ON vouch_mstr(donor_code, trans_date DESC);
CREATE INDEX IF NOT EXISTS idx_vouch_mstr_date ON vouch_mstr(trans_date DESC);
CREATE INDEX IF NOT EXISTS idx_vouch_mstr_status ON vouch_mstr(receipt_status, trns_year);
CREATE INDEX IF NOT EXISTS idx_vouch_mstr_band ON vouch_mstr(band_det_cd);

UPDATE sys_pages SET sort_order = 4 WHERE page_key = 'admin';

ON CONFLICT (page_key) DO UPDATE SET
    parent_key = EXCLUDED.parent_key,
    node_type  = EXCLUDED.node_type,
    title_en   = EXCLUDED.title_en,
    title_ar   = EXCLUDED.title_ar,
    route_path = EXCLUDED.route_path,
    sort_order = EXCLUDED.sort_order,
    is_active  = EXCLUDED.is_active;

ON CONFLICT (username) DO UPDATE SET
    full_name_ar = EXCLUDED.full_name_ar,
    full_name_en = EXCLUDED.full_name_en,
    is_active    = TRUE;

SELECT u.user_id, p.page_key,
       CASE
           WHEN UPPER(u.username) IN ('ADMIN', 'TAREK') OR u.role_id = 1 THEN 'edit'
           WHEN UPPER(u.username) IN ('SAJJAD', 'IMRAN') THEN
               CASE
                   WHEN p.page_key IN ('cash_donors', 'voucher_receipt', 'voucher_control') THEN 'edit'
                   WHEN p.page_key = 'about' THEN 'view'
                   ELSE 'none'
               END
           WHEN UPPER(u.username) = 'HASAN' THEN
               CASE
                   WHEN p.page_key = 'users' THEN 'none'
                   ELSE 'view'
               END
           ELSE 'none'
       END AS access_level,
       'SYSTEM'
FROM sys_users u
CROSS JOIN sys_pages p
WHERE p.node_type = 'page'
ON CONFLICT (user_id, page_key) DO UPDATE SET
    access_level = EXCLUDED.access_level;


